class FunctionKnowledge:
    """База знаний по функциям алгоритмов. Один return: строки отчёта."""
    def __init__(self):
        self.data = _KNOWLEDGE
        # индекс по имени и по модулю
        self._by_name = {}
        self._by_module = {}
        for key, info in self.data.items():
            self._by_name[key] = info
            mod = info.get("module")
            if mod:
                self._by_module.setdefault(mod, []).append(key)

    def topic_of(self, name):
        """Возвращает словарь-знание по имени функции. Один return: dict/None."""
        return self._by_name.get(self._norm_key(name))

    def knowledge_for(self, name):
        """Человекочитаемая строка знания про функцию. Один return: str or None."""
        info = self.topic_of(name)
        text = None
        if info:
            mod = str(info.get("module", "") or "")
            label = f" ({mod})" if mod else ""
            name_s = str(name or "")
            topic = str(info.get("topic", "") or "")
            what = str(info.get("what", "") or "")
            ex = str(info.get("ex", "") or "")
            text = (f"{name_s}{label} — {topic}.\n"
                    f"Что делает: {what}.\nПример: {ex}.")
        return text

    def module_names(self, module):
        """Имена функций модуля. Один return: list."""
        return self._by_module.get(module, [])

    def count(self):
        return len(self._by_name)

    def _norm_key(self, name):
        k = _re.sub(r"[^a-zа-яё0-9_]", "", str(name or "").lower())
        key = k
        if k in self._by_name:
            key = k
        else:
            # допускаем суффикс «()» или «функция»
            for variant in (k.rstrip("()"), k.replace("функция", "")):
                if variant in self._by_name:
                    key = variant
                    break
        return key


# синглтон
fk = FunctionKnowledge()


def _norm_q(q):
    """Нормализует строку для поиска по теме. Не-строка → «». Один return: str."""
    if not isinstance(q, str):
        return ""
    return _re.sub(r"[^а-яёa-z0-9]+", " ", q.lower()).strip()


_RU_SUFFIXES = ("оты", "оте", "ие", "ый", "ое", "ый", "ов", "ев", "ий", "ые",
                "ое", "ая", "ей", "его", "ому", "ыми", "сть", "сти", "ется",
                "ются", "ами", "ых", "нем", "тию", "ция", "ции", "ии", "ия",
                "оя", "ы", "ую", "ой", "у")

_STEM_EXC = {
    "человек": "человек", "люди": "человек", "человека": "человек",
    "ребенок": "ребенок", "ребёнок": "ребенок", "дети": "ребенок",
    "время": "врем", "времени": "врем", "временем": "врем",
    "я": "я", "она": "он", "оно": "он", "они": "они",
}


def _stem_ru(word):
    """Грубый русский стеммер для сравнения словоформ (с исключениями-основами).
    Не-строка → «». Один return: str."""
    if not isinstance(word, str):
        return ""
    cached = _STEM_CACHE.get(word)
    if cached is not None:
        return cached
    stem = _stem_ru_uncached(word)
    if len(_STEM_CACHE) < 50000:
        _STEM_CACHE[word] = stem
    return stem


def _stem_ru_uncached(word):
    """Собственно стемминг без кеша. Один return: str."""
    w = word.lower()
    stem = _STEM_EXC.get(w)
    if stem is None:
        stem = w
        for suf in _RU_SUFFIXES:
            if len(w) > len(suf) + 3 and w.endswith(suf):
                cand = w[:-len(suf)]
                if len(cand) >= 2:
                    stem = cand
                break
    return stem


# Частотные стоп-слова вопроса. Они есть почти в любом описании («соседние … так,
# что …»), поэтому их совпадение с темой/описанием не несёт смысла: «что такое
# смех» не должно превращаться в пузырьковую сортировку только потому, что у той
# в «what» написано «…так, что…». Из скоринга они исключаются.
_RU_QUESTION_STOP = {
    "что", "такое", "как", "это", "где", "кто", "зачем", "почему", "сколько",
    "какой", "какая", "какие", "каких", "каким", "чем", "чему", "про", "обо",
    "об", "о", "на", "в", "с", "по", "и", "а", "не",
    "для", "если", "то", "или", "дай", "дайте", "нужно", "надо", "можно",
    "мне", "меня", "тебе", "вас", "вы", "ты",
}


def _match_by_topic(q):
    """Ищет функцию, тема которой совпадает со словами запроса, с учётом
    словоформ (стем). Главный приоритет — ЧИСЛО слов запроса, которые функция
    покрывает, затем качество совпадения. Пустой запрос → None.
    Стоп-слова вопроса игнорируются. Один return: str/None.

    Важно: матчим ТОЛЬКО по теме и имени, не по «what»-объяснению. Общие
    глаголы внутри объяснения («работает как насос») иначе перетягивали бы
    чужое понятие: на «как работает телефон» отвечало «_сердце», потому что
    «работает» есть в тексте карточки сердца."""
    if not (q or "").strip():
        return None
    words = [_stem_ru(w) for w in _norm_q(q).split()
             if len(w) > 2 and w not in _RU_QUESTION_STOP]
    scored = []
    for name, info in (fk._by_name or {}).items():
        if not isinstance(info, dict):
            continue
        topic_tokens = {_stem_ru(t) for t in _norm_q(info.get("topic", "")).split()}
        name_norm = _norm_q(name)
        hit_words = 0
        quality = 0.0
        for w in words:
            if w in topic_tokens:
                hit_words += 1
                quality += 1.0
            elif w in name_norm:
                quality += 0.4
            elif w in _norm_q(info.get("topic", "")):
                quality += 0.2
        if hit_words or quality >= 0.4:
            # полное совпадение по теме — сильный признак
            exact_topic = bool(words and set(words) <= topic_tokens)
            scored.append((hit_words, quality, exact_topic, name))
    best_name = None
    if scored:
        # сперва точное попадание по теме, затем покрытие и качество;
        # при равенстве — лексикографически первое имя (детерминизм)
        scored.sort(key=lambda x: (-x[2], -x[0], -x[1], x[3]))
        best_name = scored[0][3]
    return best_name


def _is_inventory_q(q):
    """Запрос про «сколько/список функций»? Не-строка → False. Один return: bool."""
    if not isinstance(q, str):
        return False
    return any(w in q for w in ("сколько", "список", "все функции", "какие",
                                "перечисли", "каталог", "перечень"))


def _has_function_term(q):
    """Есть ли в запросе явный термин, про который стоит рассказывать про
    функцию (сигнальный глагол вопроса о функции/алгоритме). Пустые бытовые
    реплики («можно тебя спросить», «как дела») не считаются функциональными.
    Не-строка → False. Один return: bool."""
    if not isinstance(q, str):
        return False
    signal = any(w in q for w in ("что такое", "что делает", "расскажи про",
                                   "как работает", "объясни", "что за", "про функцию",
                                   "про алгоритм", "какой алгоритм", "какая функция",
                                   "напиши ", "как реализовать", "что значит",
                                   "что означает", "означает ли",
                                   "в чём суть", "зачем нужен", "зачем нужна",
                                   "опиши", "как устроен", "принцип работы",
                                   "какой принцип", "в чём идея", "в чём отличие",
                                   "распиши", "как устроена"))
    term = any(w in q for w in ("сортировк", "граф", "алгоритм", "функци", "модул",
                                "сложност", "бинар", "пузырьк", "ейлер", "быстр",
                                "степанове", "связ", "подграф", "поиск", "стек",
                                "очередь", "массив", "хеш", "дерево", "фибоначчи",
                                "бит", "перцептрон", "нейрон", "цикл", "рекурси",
                                "рекурс", "строк", "память", "данн"))
    return bool(signal or term)


def try_function_knowledge(query):
    """Отвечает про функцию/алгоритм по имени из запроса.
    Пустой запрос → None. Один return: str or None."""
    ans = None
    q = (query or "").lower().strip()
    if not q:
        return None
    # пустые бытовые реплики («можно тебя спросить», «как дела») не должны
    # перехватываться базой функций — требуется явный термин/сигнал
    if _has_function_term(q):
        # «что такое энтропия» — вопрос о понятии, а не о функции: карточку
        # кода отдаём только когда спрашивают про функцию/алгоритм/модуль.
        # Но если рядом стоит «что делает / как работает», речь о функции:
        # «что делает zscore что такое» — это вопрос про zscore
        asks_definition = (any(w in q for w in ("что такое", "что значит", "определение", "означает"))
                           and not any(w in q for w in ("что делает", "что делают",
                                                        "как работает", "как устроен")))
        # «хеш-функция» — не вопрос про функцию вообще: часть сложного слова
        # не делает запрос вопросом о функции
        asks_function = (("_" in q or any(w in q for w in ("функци", "алгоритм", "модул", "метод", "код", "реализ")))
                         and not _inside_compound(q, "функция") and not _inside_compound(q, "алгоритм"))
        if asks_definition and not asks_function:
            return None
        # инвентарь функций — раньше подбора по словам («сколько функций» не должно
        # перехватывать «функция Эйлера: сколько чисел...»)
        if _is_inventory_q(q) and ("функци" in q or "алгоритм" in q or "модул" in q):
            mods = sorted(getattr(fk, "_by_module", {}) or {})
            lines = [f"Знаний по функциям: {fk.count()}."]
            for m in mods:
                lines.append(f"{m}: {', '.join(fk.module_names(m))}")
            ans = "\n".join(lines)
        else:
            # ищем имя функции: точное вхождение слова или совпадение по стему
            # (распознает «бинарь», «сортировка пузырьком», падежные формы)
            q_names = _norm_q(q).split()
            q_stems = {_stem_ru(w) for w in q_names if len(w) > 2}
            # составное понятие важнее общего слова: «поиск в ширину» — это
            # обход в ширину (bfs), а не карточка общего «поиска»
            from algos import lookup
            hit = lookup.find(q)
            precise = None
            if (hit is not None and hit.get("via") == "registry"
                    and (hit.get("score") or 0) >= 0.5):
                cid = str(hit["concept"].get("id") or "").replace(" ", "_")
                if cid in (fk._by_name or {}):
                    precise = cid
            best = []
            for name in fk._by_name or {}:
                if not isinstance(name, str) or len(name) <= 2:
                    continue
                if name in (" " + q + " . , ? ! ()"):
                    best.append((2, len(name), name))
                else:
                    name_stem = _stem_ru(name)
                    if name_stem in q_stems:
                        best.append((1, len(name), name))
            found = None
            if best:
                best.sort(key=lambda x: (-x[0], -x[1]))
                found = precise or best[0][2]
            elif precise:
                found = precise
            if found:
                ans = fk.knowledge_for(found)
            else:
                # по теме описания (с учётом словоформ)
                by_topic = _match_by_topic(q)
                if by_topic:
                    ans = fk.knowledge_for(by_topic)
    return ans


def _names_a_function(q):
    """В запросе прямо названа известная функция («какая функция mean»).
    Тогда отвечает база функций, а не общее определение слова «функция».
    Один return: bool."""
    if not isinstance(q, str) or not q:
        return False
    plain = _norm_q(q)
    words = set(plain.split())
    stems = {_stem_ru(word) for word in words if len(word) > 2}
    names = [name for name in (fk._by_name or {})
             if isinstance(name, str) and len(name) > 2 and not name.startswith("_")]
    # «bubble_sort» после нормализации становится «bubble sort», поэтому
    # имя функции проверяем и с пробелом вместо подчёркивания
    return any(name in words or _stem_ru(name) in stems
               or name.replace("_", " ") in plain for name in names)


_QUESTION_WORDS = frozenset((
    "что", "такое", "кто", "такой", "такая", "какие", "какой", "какая", "как",
    "работает", "работают", "чем", "от", "и", "в", "на", "про", "это", "значит",
    "расскажи", "почему", "зачем", "устроен", "устроена", "объясни", "опиши",
    "отличие", "разница", "отличается", "сравни",
))


def _topic_covers(text, phrase):
    """Все значимые слова запроса есть в теме. Один return: bool."""
    parts = [w for w in phrase.split() if len(w) > 2]
    stems = {_stem_ru(w) for w in parts}
    # латиница («sql», «python») стеммер не берёт — сверяем словом как есть
    exact = {w.lower() for w in parts}
    words = [w for w in text.split() if len(w) > 2 and w not in _QUESTION_WORDS]
    return all(_stem_ru(w) in stems or w.lower() in exact for w in words)


def _precise_topic(q):
    """Точная составная тема из базы функций («бинарный поиск», «поиск в ширину»).
    Один return: str|None. Одиночное слово («поиск») темой не считается."""
    text = _norm_q(q)
    for cid, info in (fk._by_name or {}).items():
        if not isinstance(info, dict) or str(cid).startswith("_"):
            continue
        topic = _norm_q(str(info.get("topic") or ""))
        if topic and " " in topic and topic in text:
            return str(cid)
    from algos import lookup
    hit = lookup.find(q)
    if hit is None:
        return None
    concept = hit.get("concept") or {}
    # id в реестре печатается с пробелом («entangled pair»), ключ глоссы — с «_»
    cid = str(concept.get("id") or "").replace(" ", "_")
    keys = fk._by_name or {}
    # понятие-«_термин» из глоссы: id без подчёркивания, ключ с ним
    if cid not in keys and ("_" + cid) in keys:
        cid = "_" + cid
    if not cid or cid not in keys:
        return None
    info = fk._by_name.get(cid) or {}
    alias = _norm_q(str(hit.get("alias") or ""))
    topic = _norm_q(str(info.get("topic") or ""))
    words = set(text.split())
    # годятся и другие алиасы понятия: «квантовая запутанность» — это же
    # понятие, а не только его короткая тема «запутанность»
    variants = [alias, topic] + [str(a) for a in (concept.get("aliases") or ())]
    covering = [v for v in variants if v and _topic_covers(text, v)]
    for phrase in covering:
        # фраза целиком или точное слово темы («токен», «запутанность»);
        # общее слово-понятие («поиск») отдаём общему «_»-понятию
        if " " in phrase and phrase in text:
            return cid
        if phrase == topic and phrase in words and len(phrase) >= 3:
            return cid
    return None


def _inside_compound(query, term):
    """Термин встречается только как часть дефисного слова: «функция» в «хеш-функция».

    Такое совпадение не делает термин темой вопроса: спрашивали про хеш-функцию,
    а не про функцию вообще.
    """
    if not term or "-" not in (query or ""):
        return False
    for word in _re.split(r"[\s,.;:!?()«»\"']+", query.lower()):
        if "-" in word and term in word and word != term:
            return True
    return False


def try_definition(query):
    """Отвечает связным определением для ОБЩИХ ПОНЯТИЙ (нейросеть, ИИ, питон,
    граф, алгоритм и т.п.) своими словами — раньше сырого графа.
    Ищет понятие (ключ с префиксом «_») по совпадению термина в запросе.
    Пустой запрос → None. Один return: str|None."""
    ans = None
    q = (query or "").lower().strip()
    if not q:
        return None
    # «какая функция mean» — вопрос о функции, карточку отдаёт база функций
    asks_function = any(w in q for w in ("функци", "алгоритм", "модул", "_"))
    if _names_a_function(q) and asks_function:
        return ans
    # составная тема важнее общего «_»-понятия: «поиск в ширину» — это обход,
    # а не карточка поиска информации. Проверяем до «названа функция»: «SQL»
    # тоже есть в базе ключом, но это понятие, а не функция
    precise = _precise_topic(q)
    if precise:
        info = fk._by_name.get(precise) or {}
        topic = str(info.get("topic") or "это")
        what = str(info.get("what") or "некое понятие")
        ex = str(info.get("ex") or "")
        ans = f"{topic[0].upper() + topic[1:]} — это {what}."
        if ex.strip():
            ans += f" Например: {ex}."
        return ans
    # понятия — это ключи в _KNOWLEDGE, начинающиеся с «_»
    best = []
    for key in (fk._by_name or {}):
        if key.startswith("_"):
            info = fk._by_name[key]
            if not isinstance(info, dict):
                continue
            # матчим по первому слову topic, полному topic, явным tags
            # и по стему (чтобы распознавать падежи: «нейросетью», «граф_ом»)
            terms = [str(info.get("topic", "")).split()[0].lower()]
            full = str(info.get("topic", "")).lower()
            tags = [t.lower() for t in (info.get("tags") or [])]
            q_words = _norm_q(q).split()
            q_stems = {_stem_ru(w) for w in q_words if len(w) > 2}
            hit = None
            for t in terms:
                if t and t in q and not _inside_compound(q, t):
                    hit = len(t)
                    break
                if t and _stem_ru(t) in q_stems and not _inside_compound(q, t):
                    hit = max(hit or 0, len(t))
            if hit is None and full in q and not _inside_compound(q, full):
                hit = len(full)
            if hit is None:
                for t in tags:
                    if t and t in q and not _inside_compound(q, t):
                        hit = len(t)
                        break
                    if t and _stem_ru(t) in q_stems and not _inside_compound(q, t):
                        hit = max(hit or 0, len(t))
            if hit:
                best.append((hit,
                             str(info.get("topic", "") or ""),
                             str(info.get("what", "") or ""),
                             str(info.get("ex", "") or "")))
    if best:
        best.sort(key=lambda x: -x[0])
        _, topic, what, ex = best[0]
        topic = topic or "это"
        what = what or "некое понятие"
        ans = f"{topic[0].upper() + topic[1:]} — это {what}."
        # если примера нет — не печатаем «Например: пусто»
        if ex and str(ex).strip():
            ans += f" Например: {ex}."
    return ans


if __name__ == "__main__":
    print("функций в базе:", fk.count())
    for probe in ("что делает binary_search", "объясни gcd", "kinetic_energy", "квант запутанность"):
        print("-", probe, "->", (try_function_knowledge(probe) or "None")[:80])